const platFor=id=>STR.find(p=>(p.ids||[]).includes(id));
const platByKey=k=>STR.find(p=>p.key===k);
function strengthCard(){
 if(S.pk===undefined){const v=(typeof allV==='function'?allV():[]).find(x=>x.id===S.vid);S.pk=v&&v.pk!==undefined?v.pk:((platFor(S.vid)||{}).key||'');}
 const pk=S.pk||'';const sel=STR.slice().sort((a,b)=>a.name.localeCompare(b.name));
 const chip=(grp,val,txt)=>`<button class="chip${S[grp]===val?' on':''}" data-g="${grp}" data-v="${val}">${txt}</button>`;
 return `<div class="card"><h2><b>5</b>🔩 ${L('Αντοχή μετάδοσης: πόσο κινδυνεύεις να σπάσεις;','Driveline strength: how likely are you to break?')}</h2>
 <label>${L('Άξονες / πλατφόρμα του αυτοκινήτου','Axles / vehicle platform')}</label>
 <select id="pk"><option value="">${L('— Γενική εκτίμηση (δεν ξέρω την πλατφόρμα) —','— General estimate (platform unknown) —')}</option>${sel.map(p=>`<option value="${p.key}"${p.key===pk?' selected':''}>${p.name}</option>`).join('')}</select>
 <div class="grid" style="margin-top:10px"><div><label>${L('Μπλοκέ','Lockers')}</label><div class="chips" style="margin:0">${chip('lock','0',L('Όχι','No'))}${chip('lock','r',L('Πίσω','Rear'))}${chip('lock','fr',L('Μπρος+πίσω','Front+rear'))}</div></div>
 <div><label>${L('Πώς οδηγάς;','How do you drive?')}</label><div class="chips" style="margin:0">${chip('style','g',L('Ήπια (overland)','Gentle (overland)'))}${chip('style','t',L('Τεχνικά','Technical'))}${chip('style','h',L('Σκληρά (βράχια, γκάζι)','Hard (rocks, throttle)'))}</div></div></div>
 <div id="strout" style="margin-top:12px"></div></div>`;}
function strengthBind(){const p=document.getElementById('pk');if(!p)return;p.onchange=e=>{S.pk=e.target.value;save();render();};
 document.querySelectorAll('[data-g]').forEach(c=>c.onclick=()=>{S[c.dataset.g]=c.dataset.v;save();render();});}
function lerp2(x,x0,x1,y0,y1){return x<=x0?y0:x>=x1?y1:y0+(y1-y0)*(x-x0)/(x1-x0)}
function strengthCalc(T,m,eff,D0,D1,CR0,CRn){
 const out=document.getElementById('strout');if(!out)return;
 const p=platByKey(S.pk||'');const d0=D0/25.4,d1=D1/25.4;
 const s=p&&p.stock_tyre_in?p.stock_tyre_in:d0, ok=p?p.ok_in:s+2, ca=p?Math.max(p.caution_in,ok+0.5):s+4;
 // (α) θέση του λάστιχου πάνω στα όρια του μοντέλου
 let base=d1<=s?6:d1<=ok?lerp2(d1,s,ok,6,22):d1<=ca?lerp2(d1,ok,ca,22,55):d1<=ca+2?lerp2(d1,ca,ca+2,55,82):lerp2(d1,ca+2,ca+5,82,96);
 // (β) ροπή στους άξονες: ό,τι επιτρέπει η πρόσφυση σε βράχο (μ≈1) ή ο κινητήρας, το μικρότερο
 const ax=(cr,D)=>Math.min(T*cr*eff,1.0*m*9.81*D/2000), R=ax(CRn,D1)/ax(CR0,D0);
 const reg=CRn/CR0, mReg=reg>1.02?1+0.45*(reg-1):1;
 const mLock={'0':1,'r':1.15,'fr':1.35}[S.lock||'0'], mSty={'g':0.8,'t':1,'h':1.35}[S.style||'t'];
 const pct=Math.round(Math.min(99,Math.max(2,base*mReg*mLock*mSty)));
 const z=pct<25?[L('Χαμηλός','Low'),'#5f9e7a']:pct<50?[L('Μέτριος','Moderate'),'#e8b86d']:pct<75?[L('Υψηλός','High'),'#d97757']:[L('Πολύ υψηλός','Very high'),'#d9534f'];
 const f=(x,d=1)=>x.toLocaleString(LANG==='el'?'el-GR':'en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
 const tx=o=>o?(LANG==='el'?o.el:o.en)||'':'';
 let h=`<div style="display:flex;align-items:center;gap:14px"><div style="font-size:2.6em;font-weight:900;color:${z[1]};line-height:1">${pct}%</div>
 <div><div style="font-weight:800;color:${z[1]}">${L('Δείκτης κινδύνου θραύσης','Breakage risk index')}: ${z[0]}</div><div class="note" style="margin:2px 0 0">${L('Λάστιχο','Tyre')} ${f(d1)}″ · ${L('μόχλευση','leverage')} ${d1>=s?'+':''}${f((d1/s-1)*100,0)}% · ${L('ροπή στους άξονες','axle torque')} ${R>=1?'+':''}${f((R-1)*100,0)}% ${L('από εργοστασιακό','vs stock')}</div></div></div>
 <div style="position:relative;height:12px;border-radius:6px;margin:12px 0 4px;background:linear-gradient(90deg,#5f9e7a 0%,#5f9e7a 25%,#e8b86d 25%,#e8b86d 50%,#d97757 50%,#d97757 75%,#d9534f 75%)"><i style="position:absolute;top:-6px;left:calc(${pct}% - 2px);width:4px;height:24px;background:#fff;border-radius:2px;box-shadow:0 0 0 2px #1a1918"></i></div>
 <div class="sl"><span>${L('Χαμηλός','Low')}</span><span>${L('Μέτριος','Moderate')}</span><span>${L('Υψηλός','High')}</span><span>${L('Πολύ υψηλός','Very high')}</span></div>`;
 if(p){
  const zone=d1<=ok?L('μέσα στα όρια της εργοστασιακής μετάδοσης','within the stock driveline’s limits'):d1<=ca?L('στη ζώνη «προσοχή»: ρυθμίσεις σχέσεων, ήπιο γκάζι, συχνός έλεγχος','in the “caution” zone: regear, gentle throttle, frequent checks'):L('πάνω από το όριο: χρειάζεται ενίσχυση','above the limit: strengthening needed');
  h+=`<div class="verdict" style="border-left-color:${z[1]}"><b>${p.name}</b><br>${L('Εργοστασιακό','Stock')} ≈${f(s)}″ · ${L('ασφαλές έως','safe up to')} <b>${f(ok,0)}″</b> · ${L('προσοχή έως','caution up to')} <b>${f(ca,0)}″</b><br>${L('Με','With')} ${f(d1)}″: ${zone}.</div>
  <div class="opt"><div class="t">⚠️ ${L('Τι σπάει πρώτο','What breaks first')}<small>${tx(p.first_to_break)}</small></div></div>
  <div class="opt"><div class="t">⚙️ ${L('Άξονες','Axles')}<small>${L('Μπρος','Front')}: ${p.front?p.front.name+(p.front.type?' ('+p.front.type+')':''):'–'}<br>${L('Πίσω','Rear')}: ${p.rear?p.rear.name+(p.rear.type?' ('+p.rear.type+')':''):'–'}</small></div></div>
  <div style="margin:10px 0 4px;font-weight:800">🛠 ${L('Τι ενισχύεις και πότε','What to strengthen and when')}</div>
  ${(p.upgrades||[]).map(u=>{const now=d1>=u.from_in-0.05;return `<div style="display:flex;gap:10px;padding:8px 10px;margin:6px 0;border-radius:12px;background:${now?'#3a2a1f':'#1a1918'};border:1px solid ${now?z[1]:'var(--line)'};opacity:${now?1:.6}"><b style="white-space:nowrap;color:${now?z[1]:'var(--mut)'}">${now?'👉 ':''}${f(u.from_in,0)}″+</b><span style="font-size:.88em">${tx(u)}</span></div>`}).join('')}
  ${p.regear?`<div class="opt"><div class="t">🔁 ${L('Σχέσεις που κυκλοφορούν','Available ratios')}<small>${tx(p.regear)}</small></div></div>`:''}
  <details style="background:none;border:0;padding:0;margin:6px 0 0"><summary style="padding:6px 0;font-size:.85em">📚 ${L('Πηγές','Sources')} · ${L('αξιοπιστία','confidence')}: ${({high:L('υψηλή','high'),medium:L('μέτρια','medium'),low:L('χαμηλή','low')})[p.confidence]||'–'}</summary>
  <div class="note">${(p.sources||[]).map(u=>`<a href="${u}" target="_blank" rel="noopener" style="color:var(--blu);word-break:break-all">${u.replace(/^https?:\/\/(www\.)?/,'').slice(0,70)}</a>`).join('<br>')}</div></details>`;
 } else {
  h+=`<div class="verdict">${L('Γενική εκτίμηση από το εργοστασιακό λάστιχο: έως +2″ συνήθως ασφαλές, +2″ έως +4″ προσοχή, πάνω από +4″ θέλει ενίσχυση. Διάλεξε την πλατφόρμα σου για ακριβέστερα όρια.','General estimate from the stock tyre: up to +2″ usually safe, +2″ to +4″ caution, above +4″ needs strengthening. Pick your platform for more precise limits.')}</div>`;
 }
 h+=`<div class="note">${L('Ο δείκτης <b>δεν είναι στατιστική πιθανότητα</b>: συνδυάζει τα όρια που αναφέρουν ιδιοκτήτες και κατασκευαστές για το μοντέλο, την επιπλέον ροπή στους άξονες, τα μπλοκέ και τον τρόπο οδήγησης. Ένα χτύπημα με γκάζι μπορεί να σπάσει και εργοστασιακό αυτοκίνητο. Οι αλλαγές γίνονται μόνο από ειδικό συνεργείο.','The index <b>is not a statistical probability</b>: it combines the limits reported by owners and builders for the model, the extra axle torque, lockers and driving style. One shock load with throttle can break even a stock vehicle. Modifications only by a specialist workshop.')}</div>`;
 out.innerHTML=h;}
